import subprocess
import json

script = '''
var chrome = Application("Google Chrome");
var tab = chrome.windows[0].tabs().find(t => t.url().includes("conversation=deee59db-d892-4afa-b779-39a4e042142c"));
if (!tab) {
    "Tab not found";
} else {
    tab.execute({javascript: `
        (() => {
            const results = [];
            // Let's find message blocks or groups
            // In Grok imagine UI, each turn has role or containers
            const items = document.querySelectorAll("div.flex.flex-col.items-start, div.flex.flex-col.items-end, div[data-message-author-role]");

            // If specific selectors didn't match, let's traverse the conversation scroller
            const scroller = document.querySelector(".overflow-y-auto") || document.body;
            // Let's get all elements with class containing 'message' or 'group'
            const blocks = Array.from(document.querySelectorAll("div.group, div.relative.group"));

            // Or even better: query all paragraphs and images in chronological order
            const messageNodes = [];
            const walker = document.createTreeWalker(document.body, NodeFilter.SHOW_ELEMENT, null, false);
            let node;
            while(node = walker.nextNode()) {
                if (node.tagName === 'P' || node.tagName === 'IMG' || (node.tagName === 'DIV' && node.getAttribute('role') === 'button')) {
                    // check if inside main area
                    if (node.closest('main') || !node.closest('nav')) {
                        if (node.tagName === 'IMG' && node.src.includes('assets.grok.com')) {
                            messageNodes.push({type: 'img', src: node.src, alt: node.alt});
                        } else if (node.tagName === 'P' && node.innerText.trim()) {
                            messageNodes.push({type: 'text', text: node.innerText.trim()});
                        }
                    }
                }
            }
            return JSON.stringify(messageNodes);
        })()
    `});
}
'''

proc = subprocess.run(["osascript", "-l", "JavaScript", "-e", script], capture_output=True, text=True)
