        <td><span class="ep-cta">${r.CTA_Palabra_Clave}</span></td>
      </tr>
    `).join('');
  }

  document.getElementById('csv-search').addEventListener('input', e => renderCsvTable(e.target.value));
  renderCsvTable();
</script>
